"""Live loopback fleet report. Token kept in memory only; never in URL/storage."""
PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ChronoAgent Fleet</title>
<style>body{background:#101216;color:#e5e7eb;font:15px system-ui;margin:0}main{max-width:1120px;margin:auto;padding:32px}h1{color:#45d9cd}input,button{background:#20252c;color:inherit;border:1px solid #59616b;padding:10px;border-radius:4px}table{border-collapse:collapse;width:100%;min-width:620px;margin-bottom:28px}td,th{border-bottom:1px solid #343b44;padding:12px;text-align:left;overflow-wrap:anywhere}section{overflow-x:auto}small{color:#adb4bc}.ok{color:#77df91}.bad{color:#ff7676}button{cursor:pointer}@media(max-width:600px){main{padding:16px}table{font-size:13px}}</style>
<main><h1>ChronoAgent / Fleet</h1><form id="login"><input id="token" type="password" aria-label="Admin token" placeholder="Admin token" required><button>Connect</button></form><p id="status">Disconnected</p><section><h2>Agents</h2><table><thead><tr><th>Agent</th><th>Model</th><th>Calls</th><th>Blocked</th><th>Last seen</th></tr></thead><tbody id="agents"></tbody></table></section><section><h2>Approvals</h2><table><thead><tr><th>ID</th><th>Agent</th><th>Status</th><th>Decision</th></tr></thead><tbody id="approvals"></tbody></table></section><section><h2>Audit events</h2><table><thead><tr><th>#</th><th>Agent</th><th>Action</th><th>Time</th></tr></thead><tbody id="events"></tbody></table></section></main>
<script>
let token='',timer;
const el=id=>document.getElementById(id);
function row(target,values){const tr=document.createElement('tr');values.forEach(v=>{let td=document.createElement('td');if(v instanceof Node)td.append(v);else td.textContent=String(v??'—');tr.append(td)});el(target).append(tr)}
async function refresh(){try{const res=await fetch('/chrono/state',{headers:{'X-Chrono-Token':token}});if(!res.ok)throw Error('Access denied or service unavailable');const s=await res.json();el('status').textContent=s.audit_intact?'Connected · Audit chain intact':'Connected · Audit chain BROKEN';el('status').className=s.audit_intact?'ok':'bad';['agents','approvals','events'].forEach(id=>el(id).replaceChildren());s.agents.forEach(a=>row('agents',[a.id,a.model,a.calls,a.blocked,new Date(a.seen*1000).toLocaleString()]));s.approvals.forEach(a=>{let controls=document.createElement('span');if(a.status==='pending'&&a.expires>Date.now()/1000){[true,false].forEach(approve=>{let b=document.createElement('button');b.textContent=approve?'Approve':'Deny';b.onclick=async()=>{const actor=prompt('Human approver identity');if(!actor)return;b.disabled=true;try{let r=await fetch('/chrono/approvals/decide',{method:'POST',headers:{'Content-Type':'application/json','X-Chrono-Token':token},body:JSON.stringify({id:a.id,approve,actor})});if(!r.ok)throw Error('Decision refused');await refresh()}catch(e){el('status').textContent=e.message}finally{b.disabled=false}};controls.append(b)})}row('approvals',[a.id,a.agent,a.status,controls])});s.events.forEach(e=>row('events',[e.seq,e.agent,e.action,new Date(e.ts*1000).toLocaleString()]))}catch(e){el('status').textContent=e.message;el('status').className='bad';['agents','approvals','events'].forEach(id=>el(id).replaceChildren())}}
el('login').onsubmit=e=>{e.preventDefault();token=el('token').value;el('token').value='';clearInterval(timer);refresh();timer=setInterval(refresh,3000)};
</script></html>'''
